                    { 3, "آية المنشاوي", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "طيف نجاة — آية المنشاوي. من إصدارات قروءه.", null, "/images/products/tayf-najah.webp", "طيف نجاة", null, 130m, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), 10, true },
                    { 4, "علياء المنشاوي", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "لوحة أخيرة — علياء المنشاوي. من إصدارات قروءه.", null, "/images/products/lawha-akhira.webp", "لوحة أخيرة", null, 130m, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), 10, true },
                    { 5, "ممدوح عماد، نوران بسيوني، رنا رؤوف، آية المنشاوي", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "حلقة الذنب — ممدوح عماد، نوران بسيوني، رنا رؤوف، آية المنشاوي. من إصدارات قروءه.", null, "/images/products/halaqat-al-dhanb.webp", "حلقة الذنب", null, 130m, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), 10, true },
                    { 6, "رنا رؤوف", 4, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "طلبك مرفوض — رنا رؤوف. من إصدارات قروءه.", null, "/images/products/talabak-marfoud.webp", "طلبك مرفوض", null, 130m, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), 10, true },
                    { 7, "تامر أحمد", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "“Cerca Trova” is a gripping international thriller inspired by true stories from the world of humanitarian work. The novel follows an international delegate dedicated to Restoring Family Links, searching for relatives separated by war, disasters, and forced displacement.\n\nFrom conflict zones to fragile border crossings, each mission is a race against time, where a single document, a forgotten name, or a faint clue can reunite a family or close a chapter forever.\nCombining thrill, adventure, and deep emotional resonance, Cerca Trova transforms real humanitarian experiences into compelling fiction that is both fast-paced and profoundly human", "9789778203295", "/images/products/9789778203295.webp", "cerca trova", 552, 400m, new DateTime(2026, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), 10, false },
                    { 8, "د. خوله حمدي", 2, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "Vessels have sunk. Chaos has fallen. The rainy season has begun.\n\nAmid terrified survivors and mercenaries scrambling for escape,\nmadra is running low, and shadowed tunnels lead toward unknown fates.\n\nOne choice could save them all, or turn everything to ash.\n\nThis is not the end of the journey.\nThis is the moment of reckoning.\n\nWill Adam face the cost of his decision?\nWhat became of Rawan?\nAnd will Mike return?\n\nWho will survive… and who will be claimed by the living fire?", "9789778203400", "/images/products/9789778203400.webp", "A fire with no spark", 506, 420m, new DateTime(2026, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), 10, false },
                    { 9, "معتز شرباش", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "ماذا لو تحقّقت أمنيتك المستحيلة؟\nوماذا لو اكتشفت أن تحقيقها له ثمن؟\nزوج أناني يرى الزواج عبئًا لا يُحتمل، يستيقظ ليجد حياته انقلبت بالكامل.\nزوجته التي أنهكها التعب والشكوى، تصبح فجأة زوجة مثالية.. لا تشكو.. لا تتعب.. ولا تنام!!!\nفي البداية يبدو كل شيء مثاليًا..\nثم يبدأ الغموض. صمت غير مريح.\nنظرات لا تُفهم، وتفاصيل تختفي بلا تفسير.\nالطمأنينة تتحوّل إلى خوف صامت.\nوما حدث ليس نعمة، ولا يمكن التراجع عنه بسهولة.\nكل إجابة تقوده إلى طريق أكثر خطورة، وكل تأخير يقرّبه من خسارة لا تُعوّض.\nفي النهاية، إما أن يكسر الوهم…\nأو يختار الاستمرار… حتى النهاية.", "9789778203226", "/images/products/9789778203226.webp", "اتنين فى واحد", 306, 260m, new DateTime(2026, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), 10, false },
                    { 10, "يحيى صفوت", 3, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "ختفى ليلة تخرجه.\nسُجِّل ميتًا.\nثم عاد.\nلا ليعيش،\nبل ليواجه.\n\nعشرون عامًا من الصمت تُخفي مهمة سرية، وخيانة، وسرًا رقميًا تخشاه منظمة أقوى من دول.\nكل خطوة محسوبة.\nكل جرح مقصود.\n\nفي الشوارع، حرب بلا شهود.\nعمليات دقيقة بلا أثر.\n\nوبينما يضيق الخناق، تتكشف خطة لا تُرى،\nونهاية لا تشبه أي توقع.\n\n«رجال الهيلمان»\nعن الثمن الحقيقي للبطولة.", "9789778203363", "/images/products/9789778203363.webp", "آخر رجال الهيلمان", 368, 300m, new DateTime(2026, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), 10, false },
                    { 11, "طاهرة ماڤي", 4, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "رواية رومانسية للكاتبة طاهرة ماڤي، ترجمة ضحى صلاح، قصة مشاعر وتحوّلات تحمل الكثير من التشويق.", "9789778203134", "/images/products/9789778203134.webp", "أطلقني", 240, 330m, new DateTime(2026, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), 10, false },
                    { 12, "محمود فادي", 5, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "الكلب اللي بيعض مش دايمًا شرس، واللي بيخاف مش دايمًا ضعيف، واللي بيتجاهلك مش دايمًا عنيد\".\nالكلب قصة حقيقية أشبه بقصصنا، تجارب، وملاحظة وحياة بيعيشها بتخليه يكتسب صفاته اللي بنشوفها.", "9786339957543", "/images/products/9786339957543.webp", "أفهم كلبك", 166, 130m, new DateTime(2026, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), 10, false },
                    { 13, "هدى عبدالمنعم", 6, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "حيث يتقاطع الحب مع الأذى، تنكشف هشاشة القلب وصلابته معًا. في تلك المساحة الرمادية بين القرب والخذلان، تبدأ الحكاية.\nبين الفوضى والهوس، تعيش امرأة ممزّقة بين مسؤوليات ثقيلة، وعلاقة تُربك صورتها عن نفسها وتعيدها مرارًا إلى الدائرة ذاتها.\nلا يأتي النضج كخلاصٍ مفاجئ، بل يتشكّل ببطء، عبر محاولات متعثّرة للفهم، وحياة يومية مليئة بالأسئلة.\n\nأقرب إلى النور..\nتغوص في المناطق الخفية للعلاقات، وتفكّك الروابط التي تصوغ اختياراتنا، حين نحب بالطريقة التي تعلّمنا بها البقاء.\n\nرواية لا تعد بالنجاة السهلة، بل بالوعي، والتصالح مع الذات، حين يصبح الألم مُعلّمًا لا سجنًا، وحين نعرف لماذا تألّمنا، لا فقط كيف؛\nلتبدأ رحلة حقيقية نحو التعافي… والاقتراب أكثر من النور.", "9789778203110", "/images/products/9789778203110.webp", "أقرب إلى النور", 272, 240m, new DateTime(2026, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), 10, false },
                    { 14, "أيمن رجب طاهر", 7, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "تدور الرواية في القرن الثالث عشر، بعد هزيمة الحملة الصليبية وأسر عدد من الفرنجة في مصر.\nالبطل فارس أوروبي يقع في الأسر، يُنقل بين السجون، ويذوق الإهانة والعجز، ثم تنقلب حياته حين يخرج من الأسر إلى الحرية.\nوبسبب مرض يصيبه، يجد طريقه إلى الفسطاط، حيث تستقبله أسرة مصرية مسيحية، وتبدأ مرحلة جديدة من حياته.\nليتعرّف على مدينة نابضة، تتجاور فيها الكنيسة والمسجد والمعبد، ويخالط أطباء وعلماء ورجال دين، ويرى القاهرة والفسطاط من الداخل.\nلا كأرض عدو،\nبل كعالم إنساني نابض بالحياة.", "9789778203141", "/images/products/9789778203141.webp", "الأفرنجى", 458, 350m, new DateTime(2026, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), 10, false },
                    { 15, "عبدالرحمن شاكر", 7, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "على أرض لم تعترف يومًا بالحدود.\nتدور حكاية لا تشبه ما قيل في الأخبار.\n\nفي قلب مثلث حلايب.\nحيث يعيش شعب البجا كما عاشوا دائمًا،\nبالرعي، بانتظار المطر.\nوبعلاقة قديمة مع الأرض لا تحتاج إلى خرائط.\n\nوحين يتغير المشهد، لا يتغير المكان فقط،\nبل تتولد الأسئلة. من نحن؟\nولمن ننتمي!!\n\nرواية عن الهوية حين تصبح عبئًا.\nوعن الأرض حين تطلب ثمن البقاء.\nوعن الإنسان حين يُجبر على الاختيار.\nدون أن يكون مستعدًا.\n\nحين يصبح الانتماء أصعب من الرحيل.\nوهل الوطن قرار أم قدر؟", "9789778203370", "/images/products/9789778203370.webp", "على أوتار الباسنكوب", 242, 200m, new DateTime(2026, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), 10, false },
                    { 16, "روبرت چوردان", 2, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "في «التنين العائد»، الرواية الثالثة من ملحمة «عجلة الزمن»، يجد راند ألثور نفسه أمام خيار واحد لا مفر منه؛ أن يواجه مصيره أو يُصاب بالجنون وهو يحاول الهروب منه.\nالشتاء أوقف الحرب… لكنه لم يوقف الموت. الرجال يموتون في كل مكان وهم يهتفون باسم «التنين»، والكل يتساءل: أين هو المخلّص؟\nيقرر راند الانطلاق وحيدًا في رحلة يائسة نحو قلعة أسطورية لم تسقط قط. هناك، خلف جدران لا تُقهر، يقبع اختبار رهيب.\nالآن، يجب على مويرين ورفاقها خوض سباق محموم ضد الزمن ووحوش الظلام للحاق به، لأن فشل راند هذه المرة لا يعني الموت فحسب… بل يعني تسليم العالم لظلام أبدي.\nالنبلاء يتآمرون، والظلال تتحرك، والعالم يحبس أنفاسه… خطوة واحدة تفصل بين المخلّص المنتظر… والمجنون الذي قد يدمّر العالم.", "9789778203127", "/images/products/9789778203127.webp", "عجلة الزمن : التنين العائد (مجلدين)", 982, 875m, new DateTime(2026, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), 10, false },
                    { 17, "نرمين صلاح الدين أحمد", 3, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "ألعاب وألغاز وتسالي للكبار", "9786339957529", "/images/products/9786339957529.webp", "ألغاز وتسالي للكبار", 125, 120m, new DateTime(2026, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), 10, false },
                    { 18, "د. إبراهيم الكوني", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "عمل أدبي فلسفي معاصر للكاتب إبراهيم الكوني، من إصدارات دار كيان للنشر.", "9789778203455", "/images/products/9789778203455.webp", "الفم", 135, 165m, new DateTime(2026, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), 10, false },
                    { 19, "محمد مصطفى عرفى", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "من قرية المياسرة بدمياط إلى قلب لندن…\nحكاية رجل عادي..\nسحقه الفقر، واختبرته القسوة، وتعثر مرارًا..\nثم صعد بإرادته، وبطرق غير متساوية.\nمحمد يوسف البغدادي..\nليس استثناء، بل نموذجًا نراه كل يوم\nولا نعرف حكايته..\nرحلة عن الطموح حين يرفض الهزيمة،وعن الحياة حين ترفعك فجأة..\nثم تختبر قدرتك على البقاء..\nعن الإنسان، حين يصارع واقعه..\nويصنع مصيره بنفسه..", "9789778203189", "/images/products/9789778203189.webp", "المجاميع", 184, 180m, new DateTime(2026, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), 10, false },
                    { 20, "أحمد عصام الدين", 6, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "أجلسُ بصحبةِ قلمٍ فضيٍّ شُجَّ رأسُه، وجفَّ الجرحُ.\nأريدُ أن أحكي قبل أن يفرغ حبرُه.\nأجدُ نفسي أرسمُ مجددًا.\n\nأرسمُ أعينًا، وأبوابًا، وأمواجًا.\nأرسمُ شيخًا يحمل طفلًا لم يتقبّل فكرة انتهاء مدة اللعب.\nأرسمُ شابًا تائهًا، غارقًا في ملابس البالغين الفضفاضة.\nأرسمُ فندقًا يُعجب صاحبُه بازدحامه، ولا يفهم أن الزائر يبيت بضع ليالٍ ثم يرحل بلا عودة.\nأرسمُ صاحبَ سيركٍ يُلاعب قردًا.\nأرسمُ سريرًا، تحته مقبرةٌ تُدفن فيها الأحلام الضائعة.\n\nأتأملُ ما رسمتُه، فأجدني موجودًا في كل شيء.\nأنا الطفلُ، والشابُ، والشيخ.\nأنا صاحبُ الفندق وزبونُه.\nأنا الزائرُ والمقيم.\nأنا صاحبُ السيرك والمشاهد.\nأنا القردُ والطبلة.\nأنا الذي حفرتُ المقبرة، وأنا من بكيت.\nأنا من دفنتُ الأحلام بيدي.\n\nيئستُ من تحقيقها.\nتخلّيتُ بعدما تمسّكت.\nأطفأتُ المصباح، فاستحالت الألوانُ إلى أسودَ قاتم.\nحاولتُ أن أمحو آثارَ الأحلام، لكنها كانت تعود بعد النوم.\nتدبّ فيها الحياةُ لدقائق، لتذكّرني بأيامٍ ولّت،\nوتتساءل في أسف:\nبأيِّ ذنبٍ دُفِنتُ؟", "9789778203264", "/images/products/9789778203264.webp", "إنطفاء مصباح", 172, 180m, new DateTime(2026, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), 10, false },
                    { 21, "سيسيليا اهيرن", 6, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "تخيّل عالمًا ترى فيه الحقيقة بلا أقنعة.\nترى الناس كما هم فعلًا.\nمشاعرهم، نواياهم، أسرارهم، وحتى أكاذيبهم.\n\nمن العيش في عزلة خلف نظارات شمسية وقفازات، إلى حياة تفيض فيها الألوان بكل درجاتها، تبدأ أليس رحلة البحث عن ذات لا تذوب في الآخرين.\nرحلة شاقة نحو الفهم.\nنحو القبول.\nونحو النجاة.\n\nهذه ليست رحلة إلى الخارج، بل إلى الداخل.\nحيث المواجهة الأصعب.\n\nرواية عن رؤية ما لا يراه الآخرون.\nوعن عالم واحد… يمكن أن يُرى بألف طريقة مختلفة.", "9789778203103", "/images/products/9789778203103.webp", "بألف طريقة مختلفة", 360, 400m, new DateTime(2026, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), 10, false },
                    { 22, "رامي احمد مصطفى", 6, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "زائرة مجهولة بفستان زفاف.\nبلاغ مرتبك عن جريمة قتل.\nواختفاء يربك كل ما يبدو واضحًا.\n\nمن شذرات متفرقة ومعطيات ناقصة، أجد نفسي مدفوعةً إلى خوض تجربتي الأولى في الكتابة.\nلا بوصفها بحثًا عن حل.\nبل كتجربة يحركها الفضول والشك.\n\nالنص لا يعد بإجابات.\nولا يمنح يقينًا.\nإنه اقتراب بطيء من لغز.\nواعتراف بأن بعض القصص لا تُحكى… بل تُعاش.\n“و.م”", "9789778203356", "/images/products/9789778203356.webp", "بعض ما ورد بشأنها", 248, 230m, new DateTime(2026, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), 10, false },
                    { 23, "كيتلين شنايدرهان", 3, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "لا تؤدّي كلُّ الطرق إلى النجاة، فأحيانًا ما تكون مجرّد بداية، كأغنيةٍ بعيدة تأتي من مكانٍ مجهول، ثم تعلو.. حتى تصير صراخًا يسكن الرأس.\nفي «تحليق إيكاروس» لا تقف الكارثة عند حدود بلدة صغيرة، بل تبدأ من داخلها؛ من رغبةٍ جارفةٍ في الخلاص، من حلمٍ بأن يصبح المرء ذو قيمة، ومن خطوةٍ واحدة نحو ضوء يبدو جميلًا، يعد بالأمل.. ويُخفي الاحتراق.\nولا تبدأ الحكاية بطفلٍ صغير يختفي دون أثر، أو بوحشٍ يخرج من الظلام، بل بشابٍّ.. يظن أن الخروج من البلدة هو النجاة، وأن الموسيقى هي الوسيلة المثلى لتحقيق هدفه.\nلكن بعض الأبواب لا تُفتح إلا لتريك ما لا ينبغي أن يُرى، وبعض الفرص تعدنا بالأمل.. وتُخفي في باطنها العذاب.\n«تحليق إيكاروس» ليست مجرّد رواية عادية، بل عمل سيترك في قلبك ندبةً لا تُرى.", "9789778203257", "/images/products/9789778203257.webp", "تحليق إيكاروس", 364, 400m, new DateTime(2026, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), 10, false },
                    { 24, "طاهرة ماڤي", 4, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "نغوص مع وارنر وكينجي في بحر من المشاعر الجياشة والتفاني المطلق، بينما يواجهان سباقًا مع الزمن لإنقاذ جولييت والحفاظ على حياتها. تدخل جولييت في غيبوبة غامضة، تاركة خلفها فراغًا ثقيلًا يدفع وارنر وكينجي إلى مواجهة قرارات مصيرية.\n\nفي الوقت نفسه، يتصاعد التوتر مع احتجاز أندرسون لجيمس وآدم وبقية أطفال القادة العُليا كرهائن، ما يجعل التحديات أكثر تعقيدًا وخطورة. يزخر هذا الجزء بالمنعطفات المدهشة والأحداث غير المتوقعة التي تطرح أسئلة ملحّة: هل ستنجو جولييت؟ وكيف سيتمكن أصدقاؤها من تحرير الرهائن ومواجهة أندرسون؟ والأهم… هل سينجحون في الإطاحة بنظام «إعادة التأسيس» إلى الأبد؟", "9789778202571", "/images/products/9789778202571.webp", "تخيلني", 430, 455m, new DateTime(2026, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), 10, false },
                    { 25, "محمد عصمت", 9, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "ما خُتِمَ بالملح… لا يذوب\nفي بلدةٍ ساحليةٍ يبدو كلُّ شيءٍ مألوفًا، حتى تبدأ الأمور بالتغيّر.\nتظهر تماثيل ملح في كل مكان، على الشواطئ وفي الزوايا، بلا صانعٍ معروف، ولا سببٍ مقنع.\nيحاول الجميع التعامل معها كأسطورةٍ قديمة، أو كوسيلة دعاية جديدة، قبل أن تتطوّر الأمور، وينتشر الملح ليفرض سطوته على كل شيء، كلما ظنّ الجميع أن الأمر قد انتهى.\n\nسرعان ما يجد سليم خطّاب، كاتب الرعب الشهير، الذي يعاني من مشكلات لا يمكن لأحد تصوّرها، نفسه متورّطًا في قلب الرعب؛ ويجد نفسه محاصرًا بأسئلةٍ عليه العثور على إجابتها.\nما علاقة هذه التماثيل برواياته؟ ولماذا يبدو أن البلدة تتصرّف كمن يُخفي لعنةً قديمة؟ وهل سيحتاج للبحث عن الناجين من الأساطير المرعبة ليجد ضالته بينهم؟\n\nقبل أن يدرك أن كل إجابة تقوده إلى سؤالٍ أشدّ ظلمة، وكل خطوة تقوده نحو حقيقةٍ لا يرغب في معرفتها… حيث لا يكون الماء ماءً فقط، ولا الملح ملحًا فحسب.\n\nفي «تماثيل الملح»، تذوب الرواية بين الأسطورة القديمة، وتتداخل مع الواقع، حتى لا تعود قادرًا على الفصل بين ما تراه… وما يريدك الملح أن تراه.", "9789778203240", "/images/products/9789778203240.webp", "تماثيل الملح", 198, 200m, new DateTime(2026, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), 10, false },
                    { 26, "كارا هانتر", 3, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "رواية جريمة وإثارة وتشويق مترجمة للكاتبة كارا هانتر، تحقيق بوليسي تتكشّف فيه الأسرار خلف الأبواب المغلقة لعائلة واحدة.", "9789778203158", "/images/products/9789778203158.webp", "جريمة عائلية", 578, 490m, new DateTime(2026, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), 10, false },
                    { 27, "يحيى صفوت", 9, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "غادر كريم بيته طفلًا في ليلة بلا تفسير وبأمر من أمه، ليقضي سنوات طويلة في الغياب محمّلًا بذنب لا يهدأ، قبل أن يعود عودة وحيدة لدفنها. يعود إلى المربع السكني الذي لم يتغير في شكله، لكن أهله لم يعودوا كما كانوا، وتظل جنينة المحروقي في المنتصف صامتة، مغلقة، ومراقَبة. يكتشف كريم جيرانًا لا يتذكرهم، وتصرفات بلا تفسير، أكياسًا سوداء، روائح بخور، مفاتيح بلا أبواب، وليلة سبت لا يُسمح له أن يبقى فيها. وحين يكتشف أنه كان حاضرًا وهو غائب، وأن وفاة أمه ليست نهاية بل بداية، يتحول الفضول إلى خوف، والخوف إلى مواجهة مع أسطورة قديمة، وروح لم تغفر لنفسها، وسكان يحمون سرًا مشتركًا بأي ثمن. إنها رواية نفسية مظلمة عن الفقد، والذنب، والأماكن التي تطالبك بأغلى ما تملك قبل أن تسمح لك بالرحيل.", "9789778203318", "/images/products/9789778203318.webp", "جنينة المحروقي", 302, 260m, new DateTime(2026, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), 10, false },
                    { 28, "چيف ليندسي", 3, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "مثَّل الراكِب المُظلِم داخله وعدًا ثابتًا؛ صوتٌ يقوده، وجوعٌ لا يضل، وظلٌّ يهبه معنى.. ولو كان معنى مُلطَّخًا بالدماء.\nثم حدث ما لا يُغتفر؛ وصمت الظلام.\nلا اندفاع، ولا همس، ولا نشوة.. فقط فراغٌ بارِد يتَّسع في صدر دكستر، كقبرٍ مفتوحٍ ينتظِر صاحبه.\nلكن الصمت لا يعني الخلاص؛ فأحيانًا.. يكون فخًا، وأحيانًا أخرى يكون إعلانًا بأن شيئًا أقدم، وأقسى، قد انتبه إليه أخيرًا.\nشيء لا يُريد منه القتل.. بل يُريده هو!\nبين صفحات هذا الكِتاب، لا يُطارِد دكستر قتلةً فحسب؛ بل سؤالًا ينهش روحه؛ ماذا يتبقّى من الوحش.. حين يُسلب منه ظلامه؟\nدكستر في الظلام ليست مُجرَّد رواية.. بل سقوطٌ بطيء في ظلامٍ دامس لا قاع له.", "9789778203196", "/images/products/9789778203196.webp", "دكستر في الظلام", 420, 435m, new DateTime(2026, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), 10, false },
                    { 29, "حسن الحلبي", 9, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "بدأ كلُّ شيءٍ بصداعٍ غريب.\nظلٌّ أسود يلاحق رامي، وإحساسٌ دائم بالمراقبة.\nصرخةٌ، نزيفٌ غامض، ثم موت.\nلكن القصة لا تنتهي هنا.\n\nبعد دفنه، تصل رسائل من هاتفه.\nقبرٌ يختفي.\nوصورةٌ تكشف ظلًّا غامضًا خلفه.\nعودةٌ لم يكن ينبغي أن تحدث.\n\nحياةُ عائلةٍ تنقلب إلى لغز.\nأصدقاءُ يواجهون أسرارًا خطيرة.\nوشخصياتٌ تظهر وتختفي، بينما اسمٌ واحد يتردد في كل مكان: دونوس.\n\nمن الذي عاد فعلًا؟\nوما هو كتاب الهاشكيلا؟\nومن يقود اللعبة، ومن يحاول حماية الأرض؟\n\nروايةٌ تشويقية عن أسرارٍ قديمة،\nوصراعٍ يتجاوز الموت نفسه.", "9789778203325", "/images/products/9789778203325.webp", "دونوس", 224, 180m, new DateTime(2026, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), 10, false },
                    { 30, "إبراهيم عبدالعزيز", 7, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "كتاب طه حسين: الأيام المنسية، يعيد فتح الصفحات التي لم تُكتب..\nويكمل ما توقف عنده عميد الأدب العربي طه حسين في سيرته الأشهر.\nليست سيرة تقليدية، بل كشف مباشر عبر رسائل خاصة وأوراق شخصية ونصوص لم تُنشر من قبل.\nكتاب يضعك أمام طه حسين الحقيقي\nبعقله وشكّه وإرادته التي صنعت نورًا من العتمة.", "9789778203332", "/images/products/9789778203332.webp", "طه حسين الأيام المنسية", 372, 300m, new DateTime(2026, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), 10, false },
                    { 31, "چورچ ر.ر مارتن", 2, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "ما زالت حرب الملوك الخمسة مشتعلةً، تعاني ويلاتها جميع أنحاء الممالك السبع إلا قليلًا. على العرش الحديدي يجلس الملك الصبي الغاشم جوفري، فيما يسعى جدّه اللورد تايوين لانستر، يدُ الملك، لتأمين حكمه، ومن ثم تأمين السلطة لعائلة لانستر، مخططًا للقضاء على الملك ستانيس باراثيون الذي خرج مدحورًا من معركة الماء الأسود، وعلى الذئب الصغير روب ستارك الذي يقود حملةً في غرب البلاد رغم أنه فقد وطنه في الشمال.\n\nوفي تلك الأثناء تشقّ الملكة المنفية دينيرس تارجاريَن طريقها في قارّةٍ أخرى تُغرقها الدماء، بغية تحرير مئات الآلاف من العبيد والحصول على جيشٍ تستعيد به مملكتها، ومعها التنانين الثلاثة الحيّة الوحيدة في العالم.\n\nوفي الشمال يتحرّك جيشٌ جرّار من الهمج استعدادًا للهجوم على الجدار وغزو الممالك السبع، جيشٌ انضمّ إليه رجل حرس الليل جون سنو جاسوسًا، ولو أنّ شيئًا أسوأ منه يتقدّم من أقصى الشمال، العدوّ الحقيقي الذي ينشغل عنه الجميع تقريبًا بقتالهم، وقد لا تقدر جيوش الأرض كلّها على ردعه.", "9789778203219", "/images/products/9789778203219.webp", "عاصفة السيوف سوفت كڤر ( النسخة العالمية)", 1534, 1250m, new DateTime(2026, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), 10, false },
                    { 32, "طاهر المعتز بالله", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "الحكي أقدم وسيلة ترفيه وتعلّم في التاريخ، قبل المسرح، وقبل الكتابة، وقبل كل شيء. القصص ملأت الأديان، وشكّلت وعي البشر.\nلكن لماذا تنجح بعض القصص وتفشل أخرى؟ وما الذي يصنع الكاتب العظيم؟ الشغف، الالتزام، وحب المعرفة.\nصفات جمعت بين كتّاب وصلوا إلى قمة الإبداع، وأثبتوا أن اسم الكاتب يمكن أن يكون عنصر جذب لا يقل عن النجوم.\nنجيب محفوظ، كريستوفر نولان، وجي كي رولينج. عباقرة جمعوا بين الفن والنجاح الجماهيري، خاطبوا القلوب والعقول، وأتقنوا هندسة المشاعر.\nدروس يمكن تعلّمها، لكن يبقى السؤال: ما ثمن العبقرية، وكيف نصل إليها؟", "9789778203202", "/images/products/9789778203202.webp", "عباقرة الكتابة", 312, 250m, new DateTime(2026, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), 10, false },
                    { 33, "محمد فوزي عبد الرحيم", 3, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "بحيّ الأزبكية، نهايةَ القرنِ التاسعَ عشرَ،\nواقعةٌ من أغربِ الوقائع التي شهدتها المحروسة.\nذكرها التاريخُ باسم: يوم الفرجة،\nثم محا أثرها من أوراقه.\n\nما بين خوجةٍ ريفيٍّ هرب من الماضي،\nوامرأةٍ ذات ماضٍ ملتبسٍ سحرها الشيطان،\nوجريمةِ قتلٍ بلا قتيل،\nوصعلوكٍ يمتطي طاولاتِ المقاهي،\nيُقصّ حقيقةَ يوم الفرجة،\nالتي لا يعلمها غيره.\n\nتسافر الروايةُ عبر الزمن إلى أيامِ القاهرة الخديوية،\nوتكشف خبايا ما حدث في ذلك اليوم المشؤوم،\nفي رحلةٍ اجتمع فيها الأضدادُ على حبٍّ محرَّم وسرٍّ ملعون،\nفي وثيقةٍ يرفضها التاريخ،\nولكن لا ينكرها من شهدها.", "9789778203301", "/images/products/9789778203301.webp", "غيط النوبي", 187, 200m, new DateTime(2026, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), 10, false },
                    { 34, "محمد كامل", 3, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "بلاغ عن حريق لا يترك أثرًا.\nوقصر يخفي أكثر مما يُظهر.\nتحقيق في واقعة غامضة يقود إلى لغز يتجاوز المنطق والزمن.\n\nغرفة مرايا تفتح أبوابًا غير متوقعة.\nأزمنة تتقاطع على نحو غير متوقع.\nوتاريخ يسير في مسارات لم تحدث يومًا.\nكل انتقال يكشف سرًا جديدًا.\nوكل محاولة للعودة تقود إلى زمن أكثر خطورة.\n\nرواية تمزج التحقيق بالغموض.\nوتطرح سؤالًا واحدًا يلاحق القارئ حتى النهاية.\nهل القصر شاهد على ما حدث… أم صانع له؟", "9789778203233", "/images/products/9789778203233.webp", "قصر البارون", 216, 200m, new DateTime(2026, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), 10, false },
                    { 35, "سوزان خلقي", 6, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "على شاطئ بورتسموث، وبين غرفة ضيقة ومرافقة عجوز، تُجبر آية على مواجهة ذاتها.\nهروب من وطن موجوع، وعائلة مثقلة بالفقد، وزواج بلا صوت.\n\nصوت من الماضي، مساحة مفتوحة للاعتراف بكل ما صمتت عنه طويلًا.\nووجه من الحاضر يعيد ترتيب فوضى قلبها..\n\nإنها ليست رواية، بل سيرة وجع عربي ممتد.\nذاكرة حروب.\nمنافي أقسى من الغربة.\nونساء يحملن الهزيمة في أجسادهن، وفي أصواتهن المكبوتة.", "9789778203349", "/images/products/9789778203349.webp", "كل الظلال التي نخفيها", 254, 230m, new DateTime(2026, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), 10, false },
                    { 36, "كنزي مدبولي", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "ليست كل الحكايات تُروى بصوت واحد.\nوليست كل النساء ينجون…\nفي لستُ الأخيرة\nتتقاطع حيوات نساء من أزمنة وأماكن مختلفة..\nروما في القرن السابع عشر والإسكندرية في الحاضر.\nامرأة تصنع خلاصها بيديها.\nوأخرى تحاول إنقاذ غيرها قبل أن يفوت الأوان.\nقصص عن العنف، عن النجاة، وعن الثمن الذي تدفعه النساء حين يقررن ألا يكنّ الضحية التالية..\nرواية عن قوة تُولد من العجز،وعن رحمة قد تتحول إلى حمل ثقيل، وعن سؤال يرفض أن يختفي!!\nهل تنتهي الدائرة،أم أن هناك دائمًا ضحية جديدة؟", "9786339957536", "/images/products/9786339957536.webp", "لستُ الأخيرة", 272, 260m, new DateTime(2026, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), 10, false },
                    { 37, "محمود علام", 2, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "في اللحظة التي تظن فيها أنك تمسك هذا الكتاب، تخبرنا الفيزياء أن هناك نسخة أخرى منك ربما اختارت ألا تقرأه، ونسخة ثالثة لم تولد من الأساس... نحن نعيش في سجن من ثلاثة جدران نسميه \"الواقع الحقيقي\"، لكن العلم من وراءها يهمس بأن هذا السجن له أحد عشر بابًا مفتوحًا لا نراها!\n\nفي هذا الكتاب، سأصطحبك معي في رحلة ذهنية مذهلة عبر فيزياء الأبعاد العلوية... رحلة تبدأ من الصفر، وتصعد بك عبر درجات المكان والزمان، لتكشف لك هندسة الكون الخفية كما لم ترها من قبل، وتجيب عن أسئلة لم تخطر ببالك...\n\nهل الزمن مجرد وهم؟ وهل الماضي والمستقبل موجودان الآن معًا في مكان ما؟ كيف يفسر العلم مفهوم \"طي الواقع\"؟ وما هي العلاقة بين \"الأكوان الموازية\" ومعضلة الاختيار والاحتمالات؟ \n\nلماذا يرانا الجن ولا نراهم؟ (الإجابة هندسية بحتة!)، وكيف تلتقي أحدث نظريات \"الأوتار الفائقة\" مع حلول أعمق الألغاز الحياتية في نقطة واحدة؟\n\nهذا ليس مجرد كتاب فيزياء تقليدي... إنه تجربة فكرية وفلسفية فريدة تحاول كسر الزجاج الذي يفصل بين عقولنا وبين الحقيقة الكبرى... وأعدك أنك بعد قراءة الصفحة الأخيرة، لن تنظر إلى العالم – أو إلى نفسك – بنفس الطريقة أبدًا...", "9789778203387", "/images/products/9789778203387.webp", "ما وراء الإبعاد", 156, 165m, new DateTime(2026, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), 10, false },
                    { 38, "مصطفى قمري", 7, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "منذ أكثر من ثلاثة آلاف عام، وفي إحدى قرى مصر، توارث الناس حكايات عن مدينة كاملة اختفت من كتب التاريخ، مدينة عاشت زمن الاضطراب الذي شهدته البلاد في عهد الملك رمسيس الثالث، حين اجتاحت قبائل أجنبية تُدعى المشوش أطراف مصر، ونشرت الخراب والفساد بين القرى والبلدان، فذُبح رجال المدينة في معركة دامية، وتُركت نساؤها وحدهن في مواجهة الخوف والجوع والمجهول؛ لم يكنّ ملكات ولا أميرات، بل نساءً عاديات، منهن من حاولت النجاة بالفرار، ومنهن من أشعلت ثورة الجياع، ومن تشبثت بالسحر بحثًا عن طوق نجاة أخير.\n\nمملكة النساء ليست أسطورة، بل رواية مستوحاة من حكايات حقيقية ما زال أهل القرية يروونها حتى اليوم، رغم أنها لم تُذكر في أي كتاب تاريخي، رواية عن الصمود، وعن نساء واجهن وحدهن زمن الانهيار، وكتبن حكاياتهن، ثم اختفين من التاريخ.", "9789778203271", "/images/products/9789778203271.webp", "مملكة النساء", 368, 300m, new DateTime(2026, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), 10, false },
                    { 39, "د. خولة حمدي", 2, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "سفينة غارقة، وأسرار لم يعد ممكنًا إخفاؤها.\nبين سكان خائفين، ومرتزقة يبحثون عن النجاة…\nمادرا تتناقص، وأنفاق غامضة…\nقرار قد ينقذ الجميع، أو يحرق كل شيء…\nهذه ليست نهاية الرحلة… هذه لحظة الاختبار الحقيقي.\nهل يواجه آدم ثمن اختياره؟\nماذا حلّ بروان؟\nوهل يعود مايك…؟\nمن سينجو؟\nومن ستبتلعه النار؟", "9789778203288", "/images/products/9789778203288.webp", "نار بلا شرار", 448, 420m, new DateTime(2026, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), 10, false },
                    { 40, "احمد صلاح المهدى", 2, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "هل تسكن الأحلامُ الدوائرَ الكهربائية؟\nوهل يمكن لقلبٍ من معدنٍ أن ينبض بالحب أو الخوف؟\n\n«نبضات معدنية»\nرحلةٌ استثنائية تتجاوز حدود الخيال العلمي التقليدي،\nتدخل بنا إلى المنطقة الضبابية الفاصلة بين الإنسان والآلة.\n\nليست مجرد حكايات عن المستقبل،\nبل مرآة تعكس مخاوفنا وأحلامنا وتساؤلاتنا الوجودية.\n\nإنها دعوة لإعادة تعريف ما يعنيه أن تكون «إنسانًا» في عالمٍ تتلاشى فيه الفوارق،\nوتتحول فيه المشاعر إلى شفرات،\nوتُترجم الأحلام إلى دوائر كهربائية.", "9789778203097", "/images/products/9789778203097.webp", "نبضات معدنية", 136, 165m, new DateTime(2026, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), 10, false },
                    { 41, "حسام مصطفي ابراهيم", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "«هبوط حُرّ»\nعن الإنسان حين يُنزَع عنه الأمان: أمان الجسد، والذاكرة، والهوية، والاختيار.\n\nهنا لا يحدث الانهيار دفعةً واحدة، بل تدريجيًا، منطقيًا، وبهدوءٍ مرعب.\n\nالعالم لا يُدمَّر بالقنابل فقط، بل بالروتين، والطاعة، والخوف، والرغبة في النجاة الفردية.\nالناس يعتادون الرائحة الكريهة، ويعتادون العيش داخل الصَدَفة، ويعتادون أن يُدفنوا أحياء، وأن يُمحى ماضيهم، وأن يُدار وعيهم، وأن يُختزلوا إلى «وحدات».\nولا تحتاج السلطة هنا إلى قسوةٍ مباشرة دائمًا؛ يكفي أن تُقنع الناس أنه «ليس في الإمكان أبدع مما كان».\nوالإنسان لا يُهزم لأنه ضعيف، بل لأنه يوافق… ثم يُخفي عن نفسه أنه وافق.\nوالنهايات ليست صادمة بقدر ما هي كاشفة: العالم لا يسقط فجأة… بل يسقط سقوطًا حرًا، والإنسان يعتاد أن يسقط معه دون حتى أن يصرخ.", "9789778203394", "/images/products/9789778203394.webp", "هبوط حر", 112, 130m, new DateTime(2026, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), 10, false },
                    { 42, "چورچ ر.ر مارتن", 2, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "الجزء الرابع من سلسلة «أغنية الجليد والنار» للكاتب چورچ ر.ر مارتن، رواية فانتازيا ملحمية تتشابك فيها الصراعات على العروش والتحالفات والخيانات. النسخة العالمية.", "9789778203417", "/images/products/9789778203417.webp", "وليمة للغربان (النسخة العالمية)", 1098, 990m, new DateTime(2026, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), 10, false },
                    { 43, "محمد عصمت", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "أقسى من الموت — محمد عصمت. من إصدارات دار كيان للنشر.", null, "/images/products/aqsa-min-almawt.webp", "أقسى من الموت", null, 130m, new DateTime(2026, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), 10, false },
                    { 44, "خالد أمين", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "ساعة الذئب — خالد أمين. من إصدارات دار كيان للنشر.", null, "/images/products/saat-al-thib.webp", "ساعة الذئب", null, 130m, new DateTime(2026, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), 10, false }
                });
